INSERT INTO ledger_private.game_starter_packs VALUES('before-or-after',10,'[{"id":"timeline-practice-7c82ea2a43-6","version":5,"kind":"timeline","prompt":"Put these moments in order.","cards":[{"id":"Q123885","label":"The Royal Society is founded","art":"clock"},{"id":"Q47272","label":"Kepler space telescope launches","art":"rocket"},{"id":"Q147787","label":"Anna Karenina is first published","art":"book"},{"id":"Q184213","label":"Akashi Kaikyo Bridge is inaugurated","art":"tower"},{"id":"Q180971","label":"Apollo 17 launches","art":"rocket"}],"answer":["Q123885","Q147787","Q180971","Q184213","Q47272"],"reveal":{"Q123885":1660,"Q180971":1972,"Q147787":1877,"Q47272":2009,"Q184213":1998},"explanation":"1660 · The Royal Society is founded\n1877 · Anna Karenina is first published\n1972 · Apollo 17 launches\n1998 · Akashi Kaikyo Bridge is inaugurated\n2009 · Kepler space telescope launches","sources":["https://www.wikidata.org/wiki/Q123885","https://www.wikidata.org/wiki/Q180971","https://www.wikidata.org/wiki/Q147787","https://www.wikidata.org/wiki/Q47272","https://www.wikidata.org/wiki/Q184213"]}]'::jsonb);
INSERT INTO ledger_private.game_starter_packs VALUES('how-much-ish',1,'[{"id":"how-much-ish-v4-71","version":4,"kind":"scale","prompt":"Resize the steinway model d to match its real size.","target":{"name":"Steinway Model D","dimension":"piano length, plan view","shape":"sourced:concert-grand"},"reference":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear","measure":"2.7 m · upper usual body length"},"bounds":[0.01,100],"answer":1.01481481,"explanation":"Steinway Model D: 2.74 m (piano length, plan view). Polar bear: 2.7 m (upper usual body length). Ratio: 1.01×.\nThe Model D concert grand is 274 cm long. This profile shows its shape from above.","sources":["https://www.steinway.com/dam/jcr%3A9d156c27-487d-478c-8d2d-4dda7d47475b/918_Steinway_Brochure_11x8.5_S7.pdf","https://animals.sandiegozoo.org/animals/polar-bear"],"tag":"Music / Nature"},{"id":"how-much-ish-v4-72","version":4,"kind":"scale","prompt":"Resize the international space station to match its real size.","target":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss"},"reference":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale","measure":"18.3 m · upper adult length"},"bounds":[0.01,100],"answer":5.95628415,"explanation":"International Space Station: 109 m (end-to-end span). Humpback whale: 18.3 m (upper adult length). Ratio: 5.96×.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.nasa.gov/international-space-station/space-station-facts-and-figures/","https://www.fisheries.noaa.gov/species/humpback-whale"],"tag":"Space / Nature"},{"id":"how-much-ish-v4-73","version":4,"kind":"scale","prompt":"Resize the perseverance rover to match its real size.","target":{"name":"Perseverance rover","dimension":"chassis length","shape":"sourced:perseverance"},"reference":{"name":"Person","dimension":"reference height","shape":"sourced:human","measure":"1.75 m · reference height"},"bounds":[0.01,100],"answer":1.71428571,"explanation":"Perseverance rover: 3 m (chassis length). Person: 1.75 m (reference height). Ratio: 1.71×.\nThe chassis is about 3 m long. The robotic arm is stowed in this schematic.","sources":["https://www.jpl.nasa.gov/news/press_kits/mars_2020/launch/","Reference chosen for comparison: a 1.75 m person."],"tag":"Space / Reference"},{"id":"how-much-ish-v4-74","version":4,"kind":"scale","prompt":"Resize the table tennis table to match its real size.","target":{"name":"Table tennis table","dimension":"playing-surface length","shape":"sourced:table-tennis"},"reference":{"name":"Webb sunshield","dimension":"deployed sunshield length","shape":"sourced:webb","measure":"21.2 m · deployed sunshield length"},"bounds":[0.01,100],"answer":0.12924528,"explanation":"Table tennis table: 2.74 m (playing-surface length). Webb sunshield: 21.2 m (deployed sunshield length). Ratio: 0.13×.\nThe playing surface measures 2.74 m by 1.525 m. This schematic is a plan view.","sources":["https://documents.ittf.sport/sites/default/files/public/2026-04/ITTFCouncil_Working_Documents-2026-v1.pdf","https://science.nasa.gov/mission/webb/science-overview/science-explainers/telescope-overview/"],"tag":"Sport / Space"},{"id":"how-much-ish-v4-75","version":4,"kind":"scale","prompt":"Resize the male sperm whale to match its real size.","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m · reference length"},"bounds":[0.01,100],"answer":1.325,"explanation":"Male sperm whale: 15.9 m (mature adult length). Bus: 12 m (reference length). Ratio: 1.32×.\nMature males reach about 52 ft (15.9 m); females are smaller.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","Reference chosen for comparison: a 12 m bus."],"tag":"Nature / Reference"}]'::jsonb);
