],"answer":3.30149254,"explanation":"Saturn V: 110.6 m (height with Apollo spacecraft). Antarctic blue whale: 33.5 m (upper adult length). Ratio: 3.30×.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf","https://www.fisheries.noaa.gov/species/blue-whale"],"tag":"Space / Nature"},{"id":"how-much-ish-v4-77","version":4,"kind":"scale","prompt":"Resize the golf ball to match its real size.","target":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball"},"reference":{"name":"Ingenuity helicopter","dimension":"rotor tip-to-tip span","shape":"sourced:ingenuity","measure":"1.2 m · rotor tip-to-tip span"},"bounds":[0.01,100],"answer":0.03555833,"explanation":"Golf ball: 0.04267 m (minimum permitted diameter). Ingenuity helicopter: 1.2 m (rotor tip-to-tip span). Ratio: 0.04×.\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.","sources":["https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls","https://science.nasa.gov/mission/mars-2020-perseverance/ingenuity-mars-helicopter/"],"tag":"Sport / Space"},{"id":"how-much-ish-v4-78","version":4,"kind":"scale","prompt":"Resize the eiffel tower to match its real size.","target":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower"},"reference":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark","measure":"18.8 m · record measured length"},"bounds":[0.01,100],"answer":17.55319149,"explanation":"Eiffel Tower: 330 m (height, antenna included). Whale shark: 18.8 m (record measured length). Ratio: 17.55×.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.toureiffel.paris/en/the-monument/key-figures","https://www.georgiaaquarium.org/animal/whale-shark/"],"tag":"Architecture / Nature"}]'::jsonb);
INSERT INTO ledger_private.game_starter_packs VALUES('how-much-ish',3,'[{"id":"how-much-ish-v4-77","version":4,"kind":"scale","prompt":"Resize the golf ball to match its real size.","target":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball"},"reference":{"name":"Ingenuity helicopter","dimension":"rotor tip-to-tip span","shape":"sourced:ingenuity","measure":"1.2 m · rotor tip-to-tip span"},"bounds":[0.01,100],"answer":0.03555833,"explanation":"Golf ball: 0.04267 m (minimum permitted diameter). Ingenuity helicopter: 1.2 m (rotor tip-to-tip span). Ratio: 0.04×.\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.","sources":["https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls","https://science.nasa.gov/mission/mars-2020-perseverance/ingenuity-mars-helicopter/"],"tag":"Sport / Space"},{"id":"how-much-ish-v4-78","version":4,"kind":"scale","prompt":"Resize the eiffel tower to match its real size.","target":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower"},"reference":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark","measure":"18.8 m · record measured length"},"bounds":[0.01,100],"answer":17.55319149,"explanation":"Eiffel Tower: 330 m (height, antenna included). Whale shark: 18.8 m (record measured length). Ratio: 17.55×.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.toureiffel.paris/en/the-monument/key-figures","https://www.georgiaaquarium.org/animal/whale-shark/"],"tag":"Architecture / Nature"},{"id":"how-much-ish-v4-79","version":4,"kind":"scale","prompt":"Resize the african elephant to match its real size.","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m · height above ground"},"bounds":[0.01,100],"answer":0.03802083,"explanation":"African elephant: 7.3 m (upper adult length). Gateway Arch: 192 m (height above ground). Ratio: 0.04×.\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.nps.gov/jeff/faqs.htm"],"tag":"Nature / Architecture"},{"id":"how-much-ish-v4-80","version":4,"kind":"scale","prompt":"Resize the white rhinoceros to match its real size.","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"FIBA basketball court","dimension":"endline-to-endline length","shape":"sourced:basketball-court","measure":"28 m · endline-to-endline length"},"bounds":[0.01,100],"answer":0.14285714,"explanation":"White rhinoceros: 4 m (upper adult length). FIBA basketball court: 28 m (endline-to-endline length). Ratio: 0.14×.\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://assets.fiba.basketball/image/upload/documents-corporate-fiba-official-rules-2024-v10a.pdf"],"tag":"Nature / Sport"},{"id":"how-much-ish-v4-81","version":4,"kind":"scale","prompt":"Resize the hubble telescope to match its real size.","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m · rounded monument height"},"bounds":[0.01,100],"answer":0.07810651,"explanation":"Hubble telescope: 13.2 m (body length). Washington Monument: 169 m (rounded monument height). Ratio: 0.08×.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"],"tag":"Space / Architecture"}]'::jsonb);
INSERT INTO ledger_private.game_starter_packs VALUES('how-much-ish',4,'[{"id":"how-much-ish-v4-80","version":4,"kind":"scale","prompt":"Resize the white rhinoceros to match its real size.","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"FIBA basketball court","dimension":"endline-to-endline length","shape":"sourced:basketball-court","measure":"28 m · endline-to-endline length"},"bounds":[0.01,100],"answer":0.14285714,"explanation":"White rhinoceros: 4 m (upper adult length). FIBA basketball court: 28 m (endline-to-endline length). Ratio: 0.14×.\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://assets.fiba.basketball/image/upload/documents-corporate-fiba-official-rules-2024-v10a.pdf"],"tag":"Nature / Sport"},{"id":"how-much-ish-v4-81","version":4,"kind":"scale","prompt":"Resize the hubble telescope to match its real size.","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m · rounded monument height"},"bounds":[0.01,100],"answer":0.07810651,"explanation":"Hubble telescope: 13.2 m (body length). Washington Monument: 169 m (rounded monument height). Ratio: 0.08×.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"],"tag":"Space / Architecture"},{"id":"how-much-ish-v4-82","version":4,"kind":"scale","prompt":"Resize the gateway arch to match its real size.","target":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m · overall aircraft length"},"bounds":[0.01,100],"answer":2.64099037,"explanation":"Gateway Arch: 192 m (height above ground). Airbus A380: 72.7 m (overall aircraft length). Ratio: 2.64×.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.nps.gov/jeff/faqs.htm","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"],"tag":"Architecture / Transport"},{"id":"how-much-ish-v4-83","version":4,"kind":"scale","prompt":"Resize the male lion to match its real size.","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Table tennis table","dimension":"playing-surface length","shape":"sourced:table-tennis","measure":"2.74 m · playing-surface length"},"bounds":[0.01,100],"answer":1.29562044,"explanation":"Male lion: 3.55 m (large adult length, tail included). Table tennis table: 2.74 m (playing-surface length). Ratio: 1.30×.\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.","sources":["https://animals.sandiegozoo.org/animals/lion","https://documents.ittf.sport/sites/default/files/public/2026-04/ITTFCouncil_Working_Documents-2026-v1.pdf"],"tag":"Nature / Sport"},{"id":"how-much-ish-v4-84","version":4,"kind":"scale","prompt":"Resize the tyrannosaurus rex to match its real size.","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m · height, antenna included"},"bounds":[0.01,100],"answer":0.03636364,"explanation":"Tyrannosaurus rex: 12 m (adult length). Eiffel Tower: 330 m (height, antenna included). Ratio: 0.04×.\nAMNH gives an adult T. rex length of about 12 m.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.toureiffel.paris/en/the-monument/key-figures"],"tag":"Nature / Architecture"}]'::jsonb);
INSERT INTO ledger_private.game_starter_packs VALUES('how-much-ish',5,'[{"id":"how-much-ish-v4-83","version":4,"kind":"scale","prompt":"Resize the male lion to match its real size.","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Table tennis table","dimension":"playing-surface length","shape":"sourced:table-tennis","measure":"2.74 m · playing-surface length"},"bounds":[0.01,100],"answer":1.29562044,"explanation":"Male lion: 3.55 m (large adult length, tail included). Table tennis table: 2.74 m (playing-surface length). Ratio: 1.30×.\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.","sources":["https://animals.sandiegozoo.org/animals/lion","https://documents.ittf.sport/sites/default/files/public/2026-04/ITTFCouncil_Working_Documents-2026-v1.pdf"],"tag":"Nature / Sport"},{"id":"how-much-ish-v4-84","version":4,"kind":"scale","prompt":"Resize the tyrannosaurus rex to match its real size.","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m · height, antenna included"},"bounds":[0.01,100],"answer":0.03636364,"explanation":"Tyrannosaurus rex: 12 m (adult length). Eiffel Tower: 330 m (height, antenna included). Ratio: 0.04×.\nAMNH gives an adult T. rex length of about 12 m.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.toureiffel.paris/en/the-monument/key-figures"],"tag":"Nature / Architecture"},{"id":"how-much-ish-v4-85","version":4,"kind":"scale","prompt":"Resize the male giraffe to match its real size.","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:s